    # Tile count and tile size are separated by one-cell gutters.
    count = next(k for k in range(1, n + 1) if n == k * (k + 1))
    size = count
    out = [row[:] for row in grid]
    # Find a visible copy of the repeated motif.
    motif = None
    for tr in range(count):
        for tc in range(count):
            r0, c0 = tr * (size + 1), tc * (size + 1)
            tile = [[grid[r0 + i][c0 + j] for j in range(size)] for i in range(size)]
            if any(v == 2 for row in tile for v in row):
                motif = [[1 if v == 2 else 0 for v in row] for row in tile]
                break
        if motif is not None:
            break
    # Clear gutters/obstructions and build the marked tile array.
    for tr in range(count):
        for tc in range(count):
            r0, c0 = tr * (size + 1), tc * (size + 1)
            tile = [[grid[r0 + i][c0 + j] for j in range(size)] for i in range(size)]
            if not any(v == 2 for row in tile for v in row) and any(v == 3 for row in tile for v in row):
                if motif[tr][tc]:
                    tile = [[2 * v for v in row] for row in motif]
                else:
                    tile = [[0] * size for _ in range(size)]
            elif not any(v == 2 for row in tile for v in row):
                tile = [[0] * size for _ in range(size)]
            if motif[tr][tc] and tile[tr][tc] == 2:
                tile[tr][tc] = 8
            for i in range(size):
                for j in range(size):
                    out[r0 + i][c0 + j] = tile[i][j]
    # All one-cell gutters, including the former 3 band, are background.
    for r in range(n):
        for c in range(n):
            if r % (size + 1) == size or c % (size + 1) == size:
                out[r][c] = 0
    return out
